from pathlib import Path
from datetime import datetime,timezone
from collections import defaultdict
import csv,hashlib,json,os,secrets,shutil,sys,importlib.metadata
ROOT=Path(__file__).resolve().parents[1];OLD=ROOT.parent
SRC=Path('/home/omego/.codex/.chatgpt-projects/g-p-682bc5782a888191a87d67b2db53dfd6/revision_work/reviewer1_style_preserved/protocol')
RUN=ROOT/'runs/cpm_v2_pilot_100';assert not RUN.exists(),'Pilot already exists; never overwrite it'
RUN.mkdir();(RUN/'source').mkdir();(RUN/'epochs').mkdir();(RUN/'secrets').mkdir(mode=0o700)
for name in ['epoch_protocol.py','image_worker.py','legacy_embedder.py']:
 shutil.copyfile(SRC/name,RUN/'source'/name);(RUN/'source'/name).chmod(0o444)
# Existing cover-grouped training partition is development-only for this pilot.
manifest=OLD/'yenet_main_split_v3_2_fused075/payload_010/split_manifest.csv'
with manifest.open() as f:split=list(csv.DictReader(f))
with (ROOT/'audit/bossbase_manifest.csv').open() as f:images={x['cover_id']:x for x in csv.DictReader(f)}
groups=defaultdict(set)
for row in split:groups[images[Path(row['filename']).stem]['sha256']].add(row['split'])
leaks=[{'sha256':k,'splits':sorted(v),'cover_ids':[i for i,x in images.items() if x['sha256']==k]} for k,v in groups.items() if len(v)>1]
(ROOT/'audit/content_duplicate_split_check.json').write_text(json.dumps({'method':'byte-identical content hashes, existing 010 split','groups_crossing_partitions':leaks,'note':'New pilot excludes duplicate content. Final benchmark must group by content hash, not filename alone.'},indent=2))
exclude={i for ids in json.loads((ROOT/'audit/bossbase_verification.json').read_text())['duplicate_byte_identical_cover_groups'] for i in ids}
train=[Path(x['filename']).stem for x in split if x['split']=='train' and Path(x['filename']).stem not in exclude]
selected=sorted(set(train),key=lambda x:hashlib.sha256(('cpm-pilot-20261017:'+x).encode()).digest())[:100]
assert len(selected)==100 and not(set(selected)&exclude)
rows=[{'cover_id':i,'path':images[i]['path'],'sha256':images[i]['sha256'],'partition':'development/train'} for i in selected]
with (RUN/'cover_manifest.csv').open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=rows[0]);w.writeheader();w.writerows(rows)
shutil.copyfile(OLD/'cover_parameter/hybrid-stego/gamma1_pride_selected_seed44.txt',RUN/'gamma1_stream.txt')
shutil.copyfile(OLD/'cover_parameter/hybrid-stego/gamma2_pride_selected_seed44.txt',RUN/'gamma2_stream.txt')
master=RUN/'secrets/research_fixture_master.bin';master.write_bytes(secrets.token_bytes(32));master.chmod(0o600)
config={'run_id':'cpm_v2_pilot_100_20261017','protocol':'cpm-epoch-v2','created_at':datetime.now(timezone.utc).isoformat(),'purpose':'Engineering pilot: independent receiver recovery, fidelity, bytes and runtime; no detector or formal-security estimate','cover_count':100,'payloads_bpp':[0.1,0.2,0.4],'attempted_epochs_planned':300,'selection_rule':'SHA-256 ordering of existing training IDs with fixed public label; all byte-duplicate cover IDs excluded','historical_test_data_used':False,'session_hex':secrets.token_bytes(16).hex(),'master_file':str(master),'key_scope':'fresh research fixture only; kept local, not a production key','random_message_rule':'fresh OS-generated bytes per attempted epoch, truncated to authenticated application-bit length; originals saved for exact comparison','source_files':[{'name':p.name,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()} for p in sorted((RUN/'source').glob('*.py'))],'runtime':{'python_executable':sys.executable,'python_version':sys.version,'dependency_versions':{n:importlib.metadata.version(n) for n in ['numpy','scipy','Pillow','scikit-image','pystcstego']},'site_packages':str(OLD/'myenv/lib/python3.12/site-packages'),'threads':1},'receiver_state':'single persistent state, serial receiver process per epoch; no original cover/cost map supplied','limits':{'per_sender_timeout_sec':120,'per_receiver_timeout_sec':120,'max_attempts':300,'automatic_retry':False,'proxy_fallback':False}}
(RUN/'run_config.json').write_text(json.dumps(config,indent=2))
print(json.dumps({'run':str(RUN),'planned_epochs':300,'content_duplicate_groups_crossing_existing_partitions':len(leaks),'versions':config['runtime']['dependency_versions']},indent=2))
